SELECT DISTINCT ?graph ?subject ?predicate ?object
WHERE {
  VALUES ?graph {
    <urn:graphragprov:unit:u_97098c9bcc740322>
    <urn:graphragprov:unit:u_9869e5d2319c8ff7>
    <urn:graphragprov:unit:u_c90c433f1defefb8>
    <urn:graphragprov:unit:u_d0835ed732619207>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
    FILTER(isIRI(?subject))
  }
}
ORDER BY ?graph ?subject ?predicate ?object
